// Sends email via Resend's API (https://resend.com) over plain HTTPS.
// Reuses the exact same approach as HRMS's mailer.js. This can use the
// same Resend account as HRMS (RESEND_API_KEY can be copied over) -
// only the "from" name/signature differs, matching the "Elkay Accounts"
// identity from the original Apps Script design.

const COMPANY_NAME = process.env.COMPANY_NAME || 'Elkay Corporation';
const RESEND_API_KEY = process.env.RESEND_API_KEY;

// Until idett.co.in is verified with THIS Resend usage, sends must use
// the testing address. Once ready, set RESEND_FROM_ADDRESS to something
// like 'Elkay Accounts <accounts@idett.co.in>'.
const FROM_ADDRESS = process.env.RESEND_FROM_ADDRESS || 'Elkay Vouchering <onboarding@resend.dev>';

// ---------- SIGNATURE (fixed, matching "Elkay Accounts" from the original design) ----------
const SIGNATURE_NAME = 'Elkay Accounts';
const SIGNATURE_OFFICE_LINE = 'Corporate Office - Mumbai';
const SIGNATURE_LOGO_WIDTH = 100;
const SIGNATURE_LOGO_BASE64 =
  '';

function escapeHtml(text) {
  return String(text == null ? '' : text).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}

function signatureHtml() {
  return `
  <table cellpadding="0" cellspacing="0" border="0" style="font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#1F4E79;border-collapse:collapse;">
    <tr><td style="padding-bottom:14px;color:#1a1a2e;">Warm Regards,</td></tr>
    <tr><td style="font-weight:bold;">${SIGNATURE_NAME}</td></tr>
    <tr><td style="font-weight:bold;">${COMPANY_NAME.toUpperCase()}</td></tr>
    <tr><td style="padding-top:14px;">${SIGNATURE_OFFICE_LINE}</td></tr>
    <tr><td style="padding-top:14px;"><img src="cid:logo" alt="${COMPANY_NAME}" width="${SIGNATURE_LOGO_WIDTH}" style="display:block;border:0;max-width:${SIGNATURE_LOGO_WIDTH}px;"></td></tr>
  </table>`;
}

function wrapHtml(messagePlainText) {
  const html = escapeHtml(messagePlainText).replace(/\n/g, '<br>');
  return `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1a1a2e;">${html}<br><br>${signatureHtml()}</div>`;
}

/**
 * senderEmail identifies the logged-in Accounts/Admin person triggering
 * this send (pass req.session.user.email) so replies go to their real
 * inbox. Omit it for notifications with no logged-in trigger (e.g. a
 * Doer's public action).
 */
async function sendMail({ to, subject, text, senderEmail }) {
  if (!RESEND_API_KEY) {
    console.warn('RESEND_API_KEY not configured - skipping email send:', subject);
    return;
  }
  if (!to) return;

  const body = {
    from: FROM_ADDRESS,
    to: [to],
    subject,
    html: wrapHtml(text),
    attachments: [{ filename: 'logo.png', content: SIGNATURE_LOGO_BASE64, content_id: 'logo' }]
  };
  if (senderEmail) body.reply_to = senderEmail;

  const res = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${RESEND_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });

  if (!res.ok) {
    const errText = await res.text().catch(() => '');
    throw new Error(`Resend API error (${res.status}): ${errText}`);
  }
}

/** ---------- ADVANCE REQUESTS ---------- */

async function sendAdvanceRequestNotification(accountsEmail, doerName, requestId, purpose, amount) {
  if (!accountsEmail) return;
  await sendMail({
    to: accountsEmail,
    subject: `New Advance Request - ${requestId}`,
    text: `Hi,\n\n${doerName} has requested a cash advance.\n\n` +
      `Request ID: ${requestId}\nPurpose: ${purpose || 'Not specified'}\n` +
      `Amount Requested: Rs. ${Number(amount).toLocaleString('en-IN')}\n\n` +
      `Please review and decide in the dashboard.`
  });
}

async function sendAdvanceDecisionToDoer(doerEmail, doerName, requestId, approved, approvedAmount, senderEmail) {
  if (!doerEmail) return;
  await sendMail({
    to: doerEmail,
    subject: `Advance Request ${approved ? 'Approved' : 'Rejected'} - ${requestId}`,
    text: `Hi ${doerName},\n\nYour advance request (${requestId}) has been ${approved ? 'approved' : 'rejected'}.` +
      (approved ? `\n\nApproved Amount: Rs. ${Number(approvedAmount).toLocaleString('en-IN')}` : '') +
      `\n\nYou can view this anytime in the Vouchering portal.`,
    senderEmail
  });
}

/** ---------- TRIPS ---------- */

async function sendTripSubmittedNotification(accountsEmail, doerName, tripCode, location) {
  if (!accountsEmail) return;
  await sendMail({
    to: accountsEmail,
    subject: `Trip Submitted for Review - ${tripCode}`,
    text: `Hi,\n\n${doerName} has submitted a trip for review.\n\n` +
      `Trip Code: ${tripCode}\nLocation: ${location}\n\n` +
      `Please review and Pass/Reject in the dashboard.`
  });
}

async function sendTripDecisionToDoer(doerEmail, doerName, tripCode, approved, remark, senderEmail) {
  if (!doerEmail) return;
  await sendMail({
    to: doerEmail,
    subject: `Trip ${approved ? 'Passed' : 'Rejected'} - ${tripCode}`,
    text: `Hi ${doerName},\n\nYour trip (${tripCode}) has been ${approved ? 'passed and finalized' : 'rejected'}.` +
      (!approved && remark ? `\n\nRemark: ${remark}\n\nYou can reopen and correct it in the Vouchering portal.` : '') +
      (approved ? `\n\nThank you.` : ''),
    senderEmail
  });
}

module.exports = {
  sendMail, sendAdvanceRequestNotification, sendAdvanceDecisionToDoer,
  sendTripSubmittedNotification, sendTripDecisionToDoer
};
